<script lang="ts">
 import {onMount} from 'svelte';
 import {invoke} from '@tauri-apps/api/core';
 let status=$state<{enabled:boolean;error?:string|null;last_check?:number|null;last_request?:number|null;summary?:string;corner?:string}>({enabled:false}),busy=$state(true),error=$state('');
 async function refresh(){try{status=await invoke<typeof status>('calendar_reminder_settings');}catch{error='Calendar reminder preferences could not be loaded.';}}
 onMount(()=>{void refresh().finally(()=>busy=false);const timer=window.setInterval(()=>{if(!busy)void refresh();},5000);return ()=>window.clearInterval(timer);});
 function time(ms?:number|null){return ms?new Date(ms).toLocaleTimeString():'None this session';}
 async function corner(value:string){busy=true;error='';try{status=await invoke<typeof status>('calendar_reminder_corner',{corner:value});}catch{error='Reminder position could not be saved.';}finally{busy=false;}}
 async function configure(enabled:boolean){const previous={...status};status={...status,enabled};busy=true;error='';try{status=await invoke<typeof status>('calendar_reminder_configure',{enabled});}catch{status=previous;error='Calendar reminders could not be updated. Check system notification permission and local storage, then try again.';}finally{busy=false;}}
</script>
<div class="reminder-setting"><div><strong>Calendar reminders</strong><p>Use Outlook’s reminder settings while TAUT is running, even outside Calendar. Persistent TAUT cards include the meeting title, start time, Join, Open meeting, Snooze, and Dismiss. Cards appear on the screen containing TAUT without taking keyboard focus.</p><p>Checks run about every 30 seconds with a 31-day lookahead. Missed reminders older than two minutes are skipped after sleep or downtime. Snooze postpones this TAUT reminder locally for five minutes; it does not change Outlook.</p></div><input type="checkbox" aria-label="Calendar reminders" checked={status.enabled} disabled={busy} onchange={event=>configure(event.currentTarget.checked)}/></div>
{#if status.enabled}<label class="corner">Reminder position<select aria-label="Reminder position" disabled={busy} value={status.corner||'bottom-right'} onchange={event=>corner(event.currentTarget.value)}>{#each [['top-left','Top left'],['top-right','Top right'],['bottom-left','Bottom left'],['bottom-right','Bottom right']] as [value,label]}<option {value}>{label}</option>{/each}</select></label><div class="reminder-status" role="status" aria-label="Calendar reminder status"><p>Last check: {time(status.last_check)}<br/>Last reminder prepared: {time(status.last_request)}</p><p>{status.summary||'Waiting for the next reminder check.'}</p><small>A prepared reminder does not confirm the card appeared on screen. Only reminders due within the last two minutes are eligible.</small></div>{/if}
{#if error||status.error}<p role="alert">{error||status.error}</p>{/if}
<style>.reminder-setting{display:flex;gap:20px;align-items:center;border-top:1px solid var(--border);padding:20px 0;margin-top:20px}p{color:var(--text-secondary);font-size:13px;line-height:1.6}input{accent-color:var(--accent);width:18px;height:18px;flex:none}[role=alert]{color:var(--danger-text)}.corner{display:grid;gap:8px;font-size:13px;max-width:260px;margin:16px 0}.corner select{font:inherit;padding:8px;background:var(--surface-panel);color:var(--text-primary);border:1px solid var(--border-strong);border-radius:6px}</style>
